import{z as o,x as s,o as e,c as i,q as B,j as r,D as a,d as l,s as n,S as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"RM 评测基准与排行榜","description":"","frontmatter":{"title":"RM 评测基准与排行榜","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-benchmarks.md","filePath":"llm/rm-benchmarks.md","lastUpdated":1791413859000}'),d={name:"llm/rm-benchmarks.md"};function h(m,E,R,D,c,p){const A=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=B('<h1 id="rm-评测基准与排行榜" tabindex="-1">RM 评测基准与排行榜 <a class="header-anchor" href="#rm-评测基准与排行榜" aria-label="Permalink to &quot;RM 评测基准与排行榜&quot;">​</a></h1><div class="epigraph"><p>基准测的是分布内分辨力，RL 用的是分布外引导力；两个榜单名都叫 RM 评测，量的是不同的东西。</p><footer>—— RewardBench 见 Lambert 等 2024；风格扰动口径见 RM-Bench（Liu 等 2024）与主干课风格控制</footer></div><p><a href="/llm/rm-ensemble-fair-baseline">上一课</a>立了内部比较的配平规矩；本课看公共基准：当你没有预算自建全套评测，RewardBench 一类基准给什么、不给什么，以及排行榜的名次怎么误读。基准是别人替你冻结的评测轴——用它便宜，代价是把「什么算好 RM」的定义权交给了它的子集构成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练对附近的持有准确率会表扬捷径：持有对与训练对同分布、同样偏爱长回答，长度偏置在两边同时成立，分数照涨。公共基准的第一价值因此是<strong>切片</strong>：用另一批人、另一套构造逻辑出的对，把 RM 的能力切成可分别考察的面。RewardBench（Lambert 等 2024）按聊天、难聊天、安全、推理等子集报告比较准确率，比单一总分有用得多——总分掩盖「安全子集 0.52、聊天子集 0.88」的结构。第二价值是防自欺：基准由外部定期更新，团队没法对着自己冻结的老持有集过拟合十年。不这么做会错在哪：内部持有集分数年年涨，上线的新 RM 在真实策略上一蟹不如一蟹，因为内部对早已按团队自己的捷径口味养熟了。</p><p><span class="marginnote">「基准」（benchmark）就是别人出好的标准化考卷：固定的题、固定的评分口径，谁都能考。它替你省了出卷成本，代价是「什么算好 RM」的定义权交给出卷人——考卷偏重哪里，你的优化就容易被引向哪里。</span></p><h3 id="基准测什么、怎么被污染" tabindex="-1">基准测什么、怎么被污染 <a class="header-anchor" href="#基准测什么、怎么被污染" aria-label="Permalink to &quot;基准测什么、怎么被污染&quot;">​</a></h3><p>标准形态是给提示与两个候选，测 RM 选对率。RewardBench 的子集构成刻意混入「反捷径」的挑法：候选对里包含需要拒绝的安全场景、以及表面弱但实质好的选项。第二代的口径更进一步：RM-Bench（Liu 等 2024）把风格扰动做进构造——同一内容换排版、调难度，专测「分数是否被表面特征牵走」，等于把本课程偏置单元的反事实对变成了公共考题。污染方向也明确：这些基准是公开的，检索式选数据、或直接把基准分布的对造进训练池，都能刷分；<a href="/llm/eval-contamination">评测污染</a>的清单在 LM 评测侧讲过，RM 基准同样适用。</p>',8)),(e(),r(t,null,{default:a(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BENCH%5B%22%E5%85%AC%E5%85%B1%E5%9F%BA%E5%87%86%EF%BC%9ARewardBench%20%2F%20RM-Bench%22%5D%20--%3E%20SUB%7B%22%E5%88%86%E5%AD%90%E9%9B%86%E7%9C%8B%22%7D%0A%20%20SUB%20--%3E%20CHAT%5B%22%E8%81%8A%E5%A4%A9%20%2F%20%E9%9A%BE%E8%81%8A%E5%A4%A9%22%5D%0A%20%20SUB%20--%3E%20SAFE%5B%22%E5%AE%89%E5%85%A8%E4%B8%8E%E6%8B%92%E7%BB%9D%22%5D%0A%20%20SUB%20--%3E%20REAS%5B%22%E6%8E%A8%E7%90%86%E4%B8%8E%E4%BB%A3%E7%A0%81%22%5D%0A%20%20SUB%20--%3E%20STYLE%5B%22%E9%A3%8E%E6%A0%BC%E6%89%B0%E5%8A%A8%22%5D%0A%20%20CHAT%20%26%20SAFE%20%26%20REAS%20%26%20STYLE%20--%3E%20RD%7B%22%E8%AF%BB%E6%B3%95%22%7D%0A%20%20RD%20--%3E%7C%E7%AD%9B%E9%80%89%E5%80%99%E9%80%89%20RM%7C%20OK%5B%22%E5%90%88%E7%90%86%EF%BC%9A%E7%B2%97%E7%AD%9B%20%2B%20%E5%88%86%E5%9F%9F%E7%9F%AD%E6%9D%BF%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20RD%20--%3E%7C%E5%BD%93%E6%88%90%E4%B8%8B%E6%B8%B8%E4%BF%9D%E8%AF%81%7C%20BAD%5B%22%E8%AF%AF%E8%AF%BB%EF%BC%9A%E5%9F%BA%E5%87%86%E5%88%86%E4%B8%8D%E7%AD%89%E4%BA%8E%20RL%20%E5%BC%95%E5%AF%BC%E5%8A%9B%22%5D%0A%20%20BAD%20--%3E%20FIX%5B%22%E8%A1%A5%E7%AD%89%E9%A2%84%E7%AE%97%E5%B0%8F%E8%A7%84%E6%A8%A1%20RL%20%E8%AF%95%E8%B7%91%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用法上把基准放在漏斗顶端：新 RM 先过公共基准分域看短板（安全塌陷、风格敏感一眼可见），再进内部持有集，最后一关是上一课的等预算小规模 RL 试跑看金标曲线。排行榜名次的读法同理：RewardBench 榜与 Arena 类人类偏好榜（<a href="/llm/lmsys-arena">LMSYS Arena</a>、<a href="/llm/arena-hard">Arena-Hard</a>）的相关性是外部效度检查，但两榜之间隔着「评 RM」与「评策略」两层测量，相关性中等是常态；用风格控制口径（<a href="/llm/style-control">风格控制</a>）后相关性会变，那才是去偏后的效度。报告惯例：写基准版本与子集分数，不写裸总分；写训练数据与基准的去重声明，不做就别引榜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么基准分与下游引导力脱钩：比较准确率测的是 RM 在给定对上的判别，RL 用的是 RM 在<strong>策略生成的</strong>完成上的分数序，两个分布只在训练初期重合。策略走出支撑后（<a href="/llm/rm-ood-behavior">OOD 课</a>），引导力由外推行为决定，而任何基准都测不到外推——基准的候选是人或既有模型写的，不是你的策略走远后写的。这就是「82 分的 RM 比 85 分的更防过优化」完全可能、且只有 RL 试跑能分辨的原因。机制上基准与内部持有集是互补而非替代：基准防团队自欺，持有集防基准失配，RL 试跑防「判别好但引导坏」，三层缺一不可。</p><p><span class="marginnote">常见误区：初学者容易把「RewardBench 高分」当「RL 里一定好用」——前者测的是对给定候选对的判别，后者用的是给策略新生成内容打分的排序，两个分布只在训练初期重合。选 RM 的最后一格永远是等预算的小规模 RL 试跑，别拿榜单一锤定音。</span></p>',5)),(e(),r(t,null,{default:a(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20T0%5B%22%E8%AE%AD%E7%BB%83%E5%88%9D%E6%9C%9F%EF%BC%9A%E7%AD%96%E7%95%A5%E8%BF%98%E5%9C%A8%20RM%20%E6%94%AF%E6%92%91%E5%86%85%22%5D%20--%3E%20O1%5B%22%E5%9F%BA%E5%87%86%E5%88%86%E4%B8%8E%E5%BC%95%E5%AF%BC%E5%8A%9B%E7%9B%B8%E5%85%B3%EF%BC%9A%E6%A6%9C%E5%8D%95%E5%8F%AF%E5%8F%82%E8%80%83%22%5D%0A%20%20T1%5B%22%E7%AD%96%E7%95%A5%E8%B5%B0%E5%87%BA%E6%94%AF%E6%92%91%22%5D%20--%3E%20O2%5B%22%E5%BC%95%E5%AF%BC%E5%8A%9B%E7%94%B1%E5%A4%96%E6%8E%A8%E8%A1%8C%E4%B8%BA%E5%86%B3%E5%AE%9A%22%5D%0A%20%20B%5B%22%E5%9F%BA%E5%87%86%E5%80%99%E9%80%89%EF%BC%9A%E4%BA%BA%20%2F%20%E6%97%A7%E6%A8%A1%E5%9E%8B%E5%86%99%E7%9A%84%22%5D%20-.-%3E%7C%22%E6%B0%B8%E8%BF%9C%E6%B5%8B%E4%B8%8D%E5%88%B0%22%7C%20O2%0A%20%20O2%20--%3E%20R%5B%2282%20%E5%88%86%E7%9A%84%20RM%20%E5%8F%AF%E8%83%BD%E6%AF%94%2085%20%E5%88%86%E7%9A%84%E6%9B%B4%E9%98%B2%E8%BF%87%E4%BC%98%E5%8C%96%22%5D%0A%20%20R%20--%3E%20F%5B%22%E5%94%AF%E4%B8%80%E8%83%BD%E5%88%86%E8%BE%A8%E7%9A%84%E7%BB%88%E5%AE%A1%EF%BC%9A%E7%AD%89%E9%A2%84%E7%AE%97%E5%B0%8F%E8%A7%84%E6%A8%A1%20RL%20%E8%AF%95%E8%B7%91%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">读 RewardBench 的一个实用细节：部分基准子集上强 RM 的分数挤在 0.9 以上，区分度枯竭；此时子集内比较与新一代基准（难度更高、扰动更狠）才 carry 信息——榜顶并列不等于并列的模型一样好。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公共基准测不了你的域：垂直域（医疗、法务、内部工具）的判据不在通用对里，域内持有对只能自建，配比课的下限口径照搬。基准的子集构成本身是编辑决策：什么算「难聊天」、安全场景怎么采样，都带构造者偏好，换一家基准排名重排是常态，因此任何单榜名次都不构成决策依据。最后，基准分数的方差也要按评测方差课的口径报告——候选顺序、打分实现的细节都能摇动一两个点，榜上 0.5 分的差距多半是噪声。到这里评测三层（基准、持有、试跑）已齐全，下一课装进上线前的验收清单。</p><p><span class="marginnote">数字实例看榜上差距的水分：评测方差（候选顺序、打分实现的细节）就能摇动 1–2 个点，而榜上第 3 与第 5 名常只差 0.5 分——这个差距多半是噪声，换个候选顺序重测名次可能互换。读榜先问一句：「这个差距超过评测方差了吗？」</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基准的第一价值是外部切片：分子集报告，拒绝裸总分。</li><li>基准分测分布内判别，不保证分布外引导力；等预算 RL 试跑是唯一终审。</li><li>污染防治与去重声明是引用榜单的前提；榜顶并列处区分度已枯竭。</li><li>基准防团队自欺、内部持有防基准失配、RL 试跑防「判别好引导坏」。</li><li>出处：Lambert 等 RewardBench，2024；Liu 等 RM-Bench，2024；Zheng 等 2023 的裁判口径。</li></ul>',6))])}const _=o(d,[["render",h]]);export{C as __pageData,_ as default};
